-- Gold table distribution.DimAgent (dimension, SCD type 2).
-- Generated by `python -m dbde render` from models/gold/distribution/DimAgent.yml. Do not edit: change the spec and render again.

CREATE SCHEMA IF NOT EXISTS ${gold_catalog}.distribution;
-- GO

CREATE TABLE IF NOT EXISTS ${gold_catalog}.distribution.DimAgent (
    DimAgent_SK          BIGINT NOT NULL COMMENT 'Surrogate key of DimAgent (-1 is the unknown member).',
    Agent_BK             VARCHAR(20) NOT NULL COMMENT 'Agent code from the policy admin system.',
    AgentName            VARCHAR(200) COMMENT 'Agent full name.',
    BranchCode           VARCHAR(10) COMMENT 'Branch the agent belongs to.',
    IsActive             BOOLEAN COMMENT 'True when the agent may write new business.',
    StartDate            DATE NOT NULL COMMENT 'First date this version of the row is valid.',
    EndDate              DATE NOT NULL COMMENT 'Last date this version is valid (9999-12-31 for the current version).',
    IsCurrent            BOOLEAN NOT NULL COMMENT 'True for the current version of the row.',
    InsertLoadStepID     STRING NOT NULL COMMENT 'Load step that first wrote the row (the job run id).',
    InsertTimestamp      TIMESTAMP NOT NULL COMMENT 'When the row was first written (UTC).',
    LastUpdateLoadStepID STRING NOT NULL COMMENT 'Load step that last changed the row (the job run id).',
    LastUpdateTimestamp  TIMESTAMP NOT NULL COMMENT 'When the row was last changed (UTC).',
    CONSTRAINT DimAgent_pk PRIMARY KEY (DimAgent_SK)
)
USING DELTA
COMMENT 'One row per agent version (SCD type 2). Grain = Agent_BK, StartDate.';
-- GO

-- Columns and keys added to the spec after the first deploy.
-- Only nullable columns can be added; a type change needs a migration
-- (standards, section 7.5).
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM ${gold_catalog}.information_schema.columns
        WHERE table_schema = 'distribution' AND table_name = 'dimagent'
            AND lower(column_name) = 'agentname'
    ) THEN
        ALTER TABLE ${gold_catalog}.distribution.DimAgent ADD COLUMNS (
            AgentName VARCHAR(200) COMMENT 'Agent full name.'
        );
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM ${gold_catalog}.information_schema.columns
        WHERE table_schema = 'distribution' AND table_name = 'dimagent'
            AND lower(column_name) = 'branchcode'
    ) THEN
        ALTER TABLE ${gold_catalog}.distribution.DimAgent ADD COLUMNS (
            BranchCode VARCHAR(10) COMMENT 'Branch the agent belongs to.'
        );
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM ${gold_catalog}.information_schema.columns
        WHERE table_schema = 'distribution' AND table_name = 'dimagent'
            AND lower(column_name) = 'isactive'
    ) THEN
        ALTER TABLE ${gold_catalog}.distribution.DimAgent ADD COLUMNS (
            IsActive BOOLEAN COMMENT 'True when the agent may write new business.'
        );
    END IF;
END;
-- GO

